package ru.truetv.launcher;
import android.app.*;
import android.os.*;
import android.view.*;
import android.widget.*;

/** Short OK, focus loss and release cannot start an expert override. */
public final class HoldConfirm {
 private HoldConfirm(){}
 public static Dialog show(Activity a,String title,String explanation,Runnable confirmed){Dialog d=new Dialog(a);d.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout box=new LinearLayout(a);box.setOrientation(1);box.setPadding(Ui.dp(a,18),Ui.dp(a,16),Ui.dp(a,18),Ui.dp(a,12));box.setBackground(Ui.surface(a,Ui.panel(a),Ui.border(a),14));box.addView(Ui.label(a,title,21));TextView text=Ui.label(a,explanation,15);text.setPadding(0,Ui.dp(a,12),0,Ui.dp(a,12));box.addView(text);Button hold=Ui.tvButton(a,Ui.word(a,"Удерживайте OK 3 секунды","Hold OK for 3 seconds"));box.addView(hold);Button back=Ui.tvButton(a,Ui.word(a,"Отмена","Cancel"));box.addView(back);Handler timer=new Handler(Looper.getMainLooper());long[] start={0};boolean[] armed={false},done={false};Runnable[] tick={null};Runnable reset=()->{armed[0]=false;start[0]=0;timer.removeCallbacksAndMessages(null);hold.setText(Ui.word(a,"Удерживайте OK 3 секунды","Hold OK for 3 seconds"));};tick[0]=()->{if(!armed[0]||!hold.hasFocus()||!hold.hasWindowFocus()||!d.isShowing()||done[0])return;long elapsed=SystemClock.uptimeMillis()-start[0];if(elapsed>=3000){done[0]=true;d.dismiss();confirmed.run();return;}hold.setText(Ui.word(a,"Удерживайте: ","Keep holding: ")+String.format(java.util.Locale.ROOT,"%.1f",(3000-elapsed)/1000f)+" s");timer.postDelayed(tick[0],50);};hold.setOnKeyListener((v,key,e)->{if(key!=KeyEvent.KEYCODE_DPAD_CENTER&&key!=KeyEvent.KEYCODE_ENTER&&key!=KeyEvent.KEYCODE_NUMPAD_ENTER&&key!=KeyEvent.KEYCODE_BUTTON_A)return false;if(e.getAction()==KeyEvent.ACTION_DOWN){if(!armed[0]){armed[0]=true;start[0]=SystemClock.uptimeMillis();timer.post(tick[0]);}}else {if(armed[0]&&hold.hasFocus()&&hold.hasWindowFocus()&&SystemClock.uptimeMillis()-start[0]>=3000&&!done[0]){done[0]=true;d.dismiss();confirmed.run();}else reset.run();}return true;});hold.setOnTouchListener((v,e)->{if(e.getAction()==android.view.MotionEvent.ACTION_DOWN){hold.requestFocus();armed[0]=true;start[0]=SystemClock.uptimeMillis();timer.post(tick[0]);}else if(e.getAction()==android.view.MotionEvent.ACTION_UP||e.getAction()==android.view.MotionEvent.ACTION_CANCEL)reset.run();return true;});hold.setOnFocusChangeListener((v,focus)->{if(!focus)reset.run();});back.setOnClickListener(v->d.dismiss());d.setOnDismissListener(v->reset.run());d.setContentView(box);d.getWindow().setBackgroundDrawableResource(android.R.color.transparent);d.show();d.getWindow().setLayout(Math.min(Ui.dp(a,520),a.getResources().getDisplayMetrics().widthPixels-Ui.dp(a,32)),-2);hold.requestFocusFromTouch();d.getWindow().getDecorView().getViewTreeObserver().addOnWindowFocusChangeListener(focused->{if(!focused)reset.run();});return d;}
}
